-- =============================================================================
-- MyEnterprise — the seven business queries (generated by tools/build-sql.mjs)
-- 
-- Each query sets its own parameters first (SET @date_from …); edit them and
-- run one query at a time in the phpMyAdmin SQL tab. The PHP reports page runs
-- the same SQL from database/queries/, with the dates you choose on screen.
-- =============================================================================

USE myenterprise;

-- >>> queries/q1_category_revenue.sql
-- =============================================================================
-- Q1 · Category revenue and the leading product in each category
-- -----------------------------------------------------------------------------
-- Business question
--   Which garment categories earned the most in a period, what share of sales
--   does each represent, and which product leads each category?
-- Definitions
--   Revenue = units × the price actually paid (OrderItem.unitPrice), excluding
--   delivery fees, for orders placed in the period that were not cancelled.
--   Each product has exactly one TYPE category, so nothing is counted twice.
-- Tables (6): CustomerOrder, OrderItem, ProductVariant, Product,
--             ProductCategory, Category
-- Techniques: common table expressions, GROUP BY, window functions
--             (ROW_NUMBER and SUM … OVER) for the leader and the share.
-- =============================================================================

SET @date_from = '2026-01-01';
SET @date_to   = '2026-12-31';

WITH line_revenue AS (
  SELECT p.product_id,
         p.name                      AS product,
         o.order_id,
         oi.quantity,
         oi.quantity * oi.unitPrice  AS revenue
    FROM CustomerOrder o
    JOIN OrderItem oi      ON oi.order_id    = o.order_id
    JOIN ProductVariant pv ON pv.variant_id  = oi.variant_id
    JOIN Product p         ON p.product_id   = pv.product_id
   WHERE o.status <> 'CANCELLED'
     AND o.placedAt >= CAST(@date_from AS DATE)
     AND o.placedAt <  CAST(@date_to AS DATE) + INTERVAL 1 DAY
),
by_product AS (
  SELECT c.category_name,
         lr.product,
         SUM(lr.quantity)            AS units,
         SUM(lr.revenue)             AS revenue,
         COUNT(DISTINCT lr.order_id) AS orders
    FROM line_revenue lr
    JOIN ProductCategory pc ON pc.product_id = lr.product_id
    JOIN Category c         ON c.category_id = pc.category_id AND c.category_group = 'TYPE'
   GROUP BY c.category_name, lr.product_id, lr.product
),
ranked AS (
  SELECT bp.*,
         ROW_NUMBER() OVER (PARTITION BY category_name ORDER BY revenue DESC, product) AS position,
         SUM(revenue) OVER (PARTITION BY category_name) AS category_revenue,
         SUM(units)   OVER (PARTITION BY category_name) AS category_units,
         SUM(orders)  OVER (PARTITION BY category_name) AS category_lines
    FROM by_product bp
)
SELECT category_name                                                      AS category,
       category_units                                                     AS units_sold,
       category_revenue                                                   AS revenue,
       ROUND(100 * category_revenue / SUM(category_revenue) OVER (), 1)   AS share_pct,
       product                                                            AS top_product,
       revenue                                                            AS top_product_revenue,
       ROUND(100 * revenue / category_revenue, 1)                         AS top_product_share_pct
  FROM ranked
 WHERE position = 1
 ORDER BY category_revenue DESC;


-- >>> queries/q2_customer_value.sql
-- =============================================================================
-- Q2 · Most valuable customers and repeat purchasing
-- -----------------------------------------------------------------------------
-- Business question
--   Who are the most valuable customers in a period once refunds are taken
--   off, how often do they come back, and how much do they spend per order?
-- Definitions
--   Gross spend = order totals (items + delivery) of non-cancelled orders
--   placed in the period. Refunded = completed return refunds on those same
--   orders. Segment: 3+ orders "Loyal", 2 "Repeat", 1 "One-time".
--   Refunds are summed in their own CTE first, so joining them cannot
--   multiply the order rows.
-- Tables (6): Customer, CustomerOrder, Refund, ReturnItem, ReturnRequest,
--             OrderItem (through the refund path)
-- Techniques: CTEs, LEFT JOIN of a pre-aggregated subquery, CASE segmentation,
--             HAVING-free top-N with ORDER BY … LIMIT.
-- =============================================================================

SET @date_from = '2026-01-01';
SET @date_to   = '2026-12-31';

WITH orders_in_period AS (
  SELECT o.order_id, o.customer_id, o.totalAmount, o.placedAt
    FROM CustomerOrder o
   WHERE o.status <> 'CANCELLED'
     AND o.placedAt >= CAST(@date_from AS DATE)
     AND o.placedAt <  CAST(@date_to AS DATE) + INTERVAL 1 DAY
),
refunds AS (
  SELECT op.customer_id, SUM(r.amount) AS refunded
    FROM Refund r
    JOIN ReturnItem ri       ON ri.return_item_id    = r.return_item_id
    JOIN ReturnRequest rr    ON rr.return_request_id = ri.return_request_id
    JOIN orders_in_period op ON op.order_id          = rr.order_id
   WHERE r.status = 'COMPLETED'
   GROUP BY op.customer_id
)
SELECT CONCAT(c.firstName, ' ', c.lastName)               AS customer,
       c.email,
       COUNT(op.order_id)                                  AS orders,
       SUM(op.totalAmount)                                 AS gross_spend,
       COALESCE(MAX(rf.refunded), 0)                       AS refunded,
       SUM(op.totalAmount) - COALESCE(MAX(rf.refunded), 0) AS net_spend,
       ROUND(AVG(op.totalAmount), 2)                       AS avg_order_value,
       DATE(MIN(op.placedAt))                              AS first_order,
       DATE(MAX(op.placedAt))                              AS last_order,
       CASE WHEN COUNT(op.order_id) >= 3 THEN 'Loyal'
            WHEN COUNT(op.order_id) = 2  THEN 'Repeat'
            ELSE 'One-time' END                            AS segment
  FROM Customer c
  JOIN orders_in_period op ON op.customer_id = c.customer_id
  LEFT JOIN refunds rf     ON rf.customer_id = c.customer_id
 GROUP BY c.customer_id, c.firstName, c.lastName, c.email
 ORDER BY net_spend DESC, orders DESC
 LIMIT 15;


-- >>> queries/q3_low_stock_replenishment.sql
-- =============================================================================
-- Q3 · Low stock by warehouse and the best supplier to refill it
-- -----------------------------------------------------------------------------
-- Business question
--   Which sizes and colours are at or under their reorder level in each
--   warehouse, how much is already on order, and which supplier can refill
--   them most cheaply — at what cost and lead time?
-- Definitions
--   Available = on hand − reserved. Low = available <= reorder_level + @buffer.
--   On order = units on ORDERED purchase orders for that warehouse.
--   Suggested quantity refills to three times the reorder level, never below
--   the supplier's minimum order; 0 when open orders already cover it.
--   Best offer = lowest unit cost, then shortest lead time.
-- Tables (7): Inventory, Warehouse, ProductVariant, Product, PurchaseOrder,
--             PurchaseOrderItem, SupplierProduct, Supplier
-- Techniques: CTEs, ROW_NUMBER() to pick one offer per variant, LEFT JOIN of
--             aggregated open purchases, computed columns with GREATEST/CASE.
-- =============================================================================

SET @buffer = 0;

WITH low_stock AS (
  SELECT i.warehouse_id,
         i.variant_id,
         i.quantity_on_hand - i.quantity_reserved AS available,
         i.reorder_level
    FROM Inventory i
    JOIN ProductVariant pv ON pv.variant_id = i.variant_id AND pv.isActive = 1
    JOIN Product p         ON p.product_id  = pv.product_id AND p.isActive = 1
   WHERE i.quantity_on_hand - i.quantity_reserved <= i.reorder_level + @buffer
),
on_order AS (
  SELECT po.warehouse_id, poi.variant_id, SUM(poi.quantity) AS units
    FROM PurchaseOrder po
    JOIN PurchaseOrderItem poi ON poi.purchase_order_id = po.purchase_order_id
   WHERE po.status = 'ORDERED'
   GROUP BY po.warehouse_id, poi.variant_id
),
best_offer AS (
  SELECT sp.variant_id, s.name AS supplier, sp.unit_cost, sp.lead_time_days, sp.minimum_order_qty,
         ROW_NUMBER() OVER (PARTITION BY sp.variant_id ORDER BY sp.unit_cost, sp.lead_time_days) AS position
    FROM SupplierProduct sp
    JOIN Supplier s ON s.supplier_id = sp.supplier_id
),
planned AS (
  SELECT ls.*,
         COALESCE(oo.units, 0) AS on_order,
         GREATEST(ls.reorder_level * 3 - ls.available - COALESCE(oo.units, 0), 0) AS shortfall
    FROM low_stock ls
    LEFT JOIN on_order oo ON oo.warehouse_id = ls.warehouse_id AND oo.variant_id = ls.variant_id
)
SELECT w.name                                    AS warehouse,
       pv.sku,
       p.name                                    AS product,
       pv.configuration                          AS size,
       pv.color,
       pl.available,
       pl.reorder_level,
       pl.on_order,
       bo.supplier                               AS best_supplier,
       bo.unit_cost,
       bo.lead_time_days,
       CASE WHEN pl.shortfall = 0 THEN 0
            ELSE GREATEST(pl.shortfall, bo.minimum_order_qty) END                AS suggested_qty,
       CASE WHEN pl.shortfall = 0 THEN 0
            ELSE GREATEST(pl.shortfall, bo.minimum_order_qty) * bo.unit_cost END AS estimated_cost
  FROM planned pl
  JOIN Warehouse w        ON w.warehouse_id = pl.warehouse_id
  JOIN ProductVariant pv  ON pv.variant_id  = pl.variant_id
  JOIN Product p          ON p.product_id   = pv.product_id
  LEFT JOIN best_offer bo ON bo.variant_id  = pl.variant_id AND bo.position = 1
 ORDER BY (pl.available - pl.reorder_level), w.name, pv.sku;


-- >>> queries/q4_supplier_performance.sql
-- =============================================================================
-- Q4 · Supplier spend and delivery performance
-- -----------------------------------------------------------------------------
-- Business question
--   Which suppliers take the largest share of purchasing spend, and do they
--   deliver within the lead time they quote?
-- Definitions
--   Spend = quantity × unit cost on purchase orders placed in the period,
--   excluding cancelled orders. Quoted lead time of a purchase order = the
--   longest quoted lead time among its lines (SupplierProduct). Actual lead
--   time = receivedAt − orderedAt in days, for received orders only.
--   On time = received within the quoted lead time.
-- Tables (4): Supplier, PurchaseOrder, PurchaseOrderItem, SupplierProduct
-- Techniques: CTE that aggregates per purchase order first (so lines are not
--             double counted), conditional aggregation (SUM/AVG over CASE),
--             DATEDIFF, correlated subquery for the size of the price list.
-- =============================================================================

SET @date_from = '2026-01-01';
SET @date_to   = '2026-12-31';

WITH po_summary AS (
  SELECT po.purchase_order_id,
         po.supplier_id,
         po.status,
         po.orderedAt,
         po.receivedAt,
         SUM(poi.quantity * poi.unit_cost) AS order_value,
         SUM(poi.quantity)                 AS units,
         MAX(sp.lead_time_days)            AS quoted_days
    FROM PurchaseOrder po
    JOIN PurchaseOrderItem poi    ON poi.purchase_order_id = po.purchase_order_id
    LEFT JOIN SupplierProduct sp  ON sp.supplier_id = po.supplier_id AND sp.variant_id = poi.variant_id
   WHERE po.orderedAt >= CAST(@date_from AS DATE)
     AND po.orderedAt <  CAST(@date_to AS DATE) + INTERVAL 1 DAY
   GROUP BY po.purchase_order_id, po.supplier_id, po.status, po.orderedAt, po.receivedAt
)
SELECT s.name                                                                   AS supplier,
       COUNT(*)                                                                 AS purchase_orders,
       SUM(ps.status = 'RECEIVED')                                              AS received,
       SUM(ps.status = 'ORDERED')                                               AS open_orders,
       SUM(CASE WHEN ps.status <> 'CANCELLED' THEN ps.units END)                AS units,
       SUM(CASE WHEN ps.status <> 'CANCELLED' THEN ps.order_value END)          AS spend,
       ROUND(100 * SUM(CASE WHEN ps.status <> 'CANCELLED' THEN ps.order_value END)
                 / SUM(SUM(CASE WHEN ps.status <> 'CANCELLED' THEN ps.order_value END)) OVER (), 1) AS spend_share_pct,
       ROUND(AVG(ps.quoted_days), 1)                                            AS avg_quoted_days,
       ROUND(AVG(CASE WHEN ps.status = 'RECEIVED'
                      THEN DATEDIFF(ps.receivedAt, ps.orderedAt) END), 1)       AS avg_actual_days,
       ROUND(100 * AVG(CASE WHEN ps.status = 'RECEIVED'
                            THEN DATEDIFF(ps.receivedAt, ps.orderedAt) <= ps.quoted_days END), 0) AS on_time_pct,
       (SELECT COUNT(*) FROM SupplierProduct sp2 WHERE sp2.supplier_id = s.supplier_id) AS variants_offered
  FROM Supplier s
  JOIN po_summary ps ON ps.supplier_id = s.supplier_id
 GROUP BY s.supplier_id, s.name
 ORDER BY spend DESC;


-- >>> queries/q5_fulfillment_backlog.sql
-- =============================================================================
-- Q5 · Fulfillment backlog: paid orders not yet delivered
-- -----------------------------------------------------------------------------
-- Business question
--   Which paid orders are still waiting to be packed, shipped or delivered,
--   how long has each waited, which warehouses hold the units, and who is
--   packing them?
-- Definitions
--   Open = PLACED, PROCESSING or SHIPPED. Hours waiting are counted from
--   placedAt to @as_of (NOW() when @as_of is NULL). An order is "overdue"
--   when it has not shipped within 48 hours (standard) or 24 hours (express).
--   Units and allocations are aggregated in separate derived tables so the
--   two one-to-many joins cannot multiply each other.
-- Tables (7): CustomerOrder, Customer, OrderItem, Fulfillment, Admin,
--             OrderAllocation, Warehouse, Shipment
-- Techniques: derived tables, conditional SUM, GROUP_CONCAT, TIMESTAMPDIFF,
--             CASE for the stage and overdue flag.
-- =============================================================================

SET @as_of = NULL;

SELECT o.orderNumber                                               AS order_number,
       CONCAT(c.firstName, ' ', c.lastName)                        AS customer,
       o.status,
       o.deliveryMethod                                            AS delivery,
       o.placedAt                                                  AS placed_at,
       TIMESTAMPDIFF(HOUR, o.placedAt, COALESCE(@as_of, NOW()))    AS hours_waiting,
       items.units                                                 AS units,
       COALESCE(alloc.reserved_units, 0)                           AS units_to_ship,
       COALESCE(alloc.shipped_units, 0)                            AS units_shipped,
       alloc.warehouses,
       COALESCE(par.in_transit, 0)                                 AS parcels_in_transit,
       COALESCE(a.fullName, 'Unassigned')                          AS packer,
       CASE o.status WHEN 'PLACED'     THEN 'Waiting to be picked'
                     WHEN 'PROCESSING' THEN 'Being packed'
                     ELSE 'With the carrier' END                   AS stage,
       CASE WHEN o.status IN ('PLACED', 'PROCESSING')
             AND TIMESTAMPDIFF(HOUR, o.placedAt, COALESCE(@as_of, NOW()))
                 > IF(o.deliveryMethod = 'EXPRESS', 24, 48)
            THEN 'Overdue' ELSE 'On track' END                     AS sla
  FROM CustomerOrder o
  JOIN Customer c    ON c.customer_id = o.customer_id
  JOIN Fulfillment f ON f.order_id    = o.order_id
  LEFT JOIN Admin a  ON a.admin_id    = f.admin_id
  JOIN (SELECT order_id, SUM(quantity) AS units
          FROM OrderItem GROUP BY order_id) items ON items.order_id = o.order_id
  LEFT JOIN (SELECT oa.fulfillment_id,
                    SUM(CASE WHEN oa.status = 'RESERVED' THEN oa.allocated_qty ELSE 0 END) AS reserved_units,
                    SUM(CASE WHEN oa.status = 'SHIPPED'  THEN oa.allocated_qty ELSE 0 END) AS shipped_units,
                    GROUP_CONCAT(DISTINCT w.name ORDER BY w.name SEPARATOR ', ')            AS warehouses
               FROM OrderAllocation oa
               JOIN Warehouse w ON w.warehouse_id = oa.warehouse_id
              WHERE oa.status <> 'RELEASED'
              GROUP BY oa.fulfillment_id) alloc ON alloc.fulfillment_id = f.fulfillment_id
  LEFT JOIN (SELECT fulfillment_id, SUM(status = 'IN_TRANSIT') AS in_transit
               FROM Shipment GROUP BY fulfillment_id) par ON par.fulfillment_id = f.fulfillment_id
 WHERE o.status IN ('PLACED', 'PROCESSING', 'SHIPPED')
 ORDER BY FIELD(o.status, 'PLACED', 'PROCESSING', 'SHIPPED'), o.placedAt;


-- >>> queries/q6_returns_by_product.sql
-- =============================================================================
-- Q6 · Return rates, reasons and refunds by product
-- -----------------------------------------------------------------------------
-- Business question
--   Which products come back most often relative to what was delivered, what
--   is the main reason, and how much money has been refunded for them?
-- Definitions
--   Cohort = orders placed in the period. Units delivered = units on those
--   orders that reached DELIVERED. Units returned = units on non-rejected
--   return requests for the same orders. Return rate = returned / delivered.
--   Refunded = COMPLETED refunds. Each measure is aggregated in its own CTE
--   before joining, so one-to-many joins cannot inflate the numbers.
-- Tables (7): Product, ProductVariant, OrderItem, CustomerOrder, ReturnItem,
--             ReturnRequest, Refund
-- Techniques: four CTEs, ROW_NUMBER() for the most common reason,
--             NULLIF to avoid division by zero.
-- =============================================================================

SET @date_from = '2026-01-01';
SET @date_to   = '2026-12-31';

WITH cohort AS (
  SELECT oi.order_item_id, oi.quantity, pv.product_id, o.status
    FROM CustomerOrder o
    JOIN OrderItem oi      ON oi.order_id   = o.order_id
    JOIN ProductVariant pv ON pv.variant_id = oi.variant_id
   WHERE o.placedAt >= CAST(@date_from AS DATE)
     AND o.placedAt <  CAST(@date_to AS DATE) + INTERVAL 1 DAY
),
delivered AS (
  SELECT product_id, SUM(quantity) AS units_delivered
    FROM cohort WHERE status = 'DELIVERED'
   GROUP BY product_id
),
returned AS (
  SELECT co.product_id,
         SUM(ri.quantity)                     AS units_returned,
         COUNT(DISTINCT rr.return_request_id) AS return_requests
    FROM ReturnItem ri
    JOIN ReturnRequest rr ON rr.return_request_id = ri.return_request_id
    JOIN cohort co        ON co.order_item_id     = ri.order_item_id
   WHERE rr.status <> 'REJECTED'
   GROUP BY co.product_id
),
refunded AS (
  SELECT co.product_id, SUM(r.amount) AS refunded
    FROM Refund r
    JOIN ReturnItem ri ON ri.return_item_id = r.return_item_id
    JOIN cohort co     ON co.order_item_id  = ri.order_item_id
   WHERE r.status = 'COMPLETED'
   GROUP BY co.product_id
),
reasons AS (
  SELECT co.product_id, rr.reason,
         ROW_NUMBER() OVER (PARTITION BY co.product_id ORDER BY COUNT(*) DESC, rr.reason) AS position
    FROM ReturnRequest rr
    JOIN ReturnItem ri ON ri.return_request_id = rr.return_request_id
    JOIN cohort co     ON co.order_item_id     = ri.order_item_id
   WHERE rr.status <> 'REJECTED'
   GROUP BY co.product_id, rr.reason
)
SELECT p.name                                                                 AS product,
       p.brand,
       d.units_delivered,
       r.units_returned,
       r.return_requests,
       ROUND(100 * r.units_returned / NULLIF(d.units_delivered, 0), 1)        AS return_rate_pct,
       COALESCE(f.refunded, 0)                                                AS refunded,
       rs.reason                                                              AS top_reason
  FROM returned r
  JOIN Product p        ON p.product_id  = r.product_id
  LEFT JOIN delivered d ON d.product_id  = r.product_id
  LEFT JOIN refunded f  ON f.product_id  = r.product_id
  LEFT JOIN reasons rs  ON rs.product_id = r.product_id AND rs.position = 1
 ORDER BY return_rate_pct DESC, r.units_returned DESC, p.name;


-- >>> queries/q7_warranty_claims.sql
-- =============================================================================
-- Q7 · Quality-guarantee claims and their eligibility
-- -----------------------------------------------------------------------------
-- Business question
--   Which quality-guarantee claims are open, was each one made inside its
--   guarantee period, and which products and customers are affected?
-- Definitions
--   The guarantee starts when the parcel carrying the item is delivered and
--   lasts Warranty.duration_months (fn_warranty_expires_on). A claim is
--   "Eligible" when it was submitted on or before that date. With
--   @only_open = 1 only SUBMITTED and APPROVED claims are listed.
-- Tables (7): WarrantyClaim, Warranty, OrderItem, CustomerOrder, Customer,
--             ProductVariant, Product  (+ OrderAllocation/Shipment via the function)
-- Techniques: stored function inside a query, DATEDIFF, CASE, FIELD() ordering.
-- =============================================================================

SET @only_open = 0;

SELECT CONCAT('WC-', wc.claim_id)                                         AS claim,
       p.name                                                             AS product,
       CONCAT(pv.configuration, ' · ', pv.color)                          AS variant,
       CONCAT(c.firstName, ' ', c.lastName)                               AS customer,
       o.orderNumber                                                      AS order_number,
       w.duration_months                                                  AS guarantee_months,
       fn_warranty_expires_on(wc.order_item_id, wc.warranty_id)           AS covered_until,
       DATE(wc.submittedAt)                                               AS submitted_on,
       DATEDIFF(fn_warranty_expires_on(wc.order_item_id, wc.warranty_id),
                DATE(wc.submittedAt))                                     AS days_left_at_claim,
       CASE WHEN DATE(wc.submittedAt) <= fn_warranty_expires_on(wc.order_item_id, wc.warranty_id)
            THEN 'Eligible' ELSE 'Outside guarantee' END                  AS eligibility,
       wc.status,
       wc.reason,
       wc.resolution
  FROM WarrantyClaim wc
  JOIN Warranty w        ON w.warranty_id    = wc.warranty_id
  JOIN OrderItem oi      ON oi.order_item_id = wc.order_item_id
  JOIN CustomerOrder o   ON o.order_id       = oi.order_id
  JOIN Customer c        ON c.customer_id    = o.customer_id
  JOIN ProductVariant pv ON pv.variant_id    = oi.variant_id
  JOIN Product p         ON p.product_id     = pv.product_id
 WHERE @only_open = 0 OR wc.status IN ('SUBMITTED', 'APPROVED')
 ORDER BY FIELD(wc.status, 'SUBMITTED', 'APPROVED', 'RESOLVED', 'REJECTED'), wc.submittedAt DESC;
